854	/// Get information about the process(es) attached to the backend. Returns
855	/// `null` if there was an error getting the information or the information is
856	/// not available on a particular platform.
  1	const std = @import("std");
  2	const Allocator = std.mem.Allocator;
  3	const posix = std.posix;
  4	const renderer = @import("../renderer.zig");
  5	const terminal = @import("../terminal/main.zig");
  6	const termio = @import("../termio.zig");
  7	const ProcessInfo = @import("../pty.zig").ProcessInfo;
  8	
  9	// The preallocation size for the write request pool. This should be big
 10	// enough to satisfy most write requests. It must be a power of 2.
 11	const WRITE_REQ_PREALLOC = std.math.pow(usize, 2, 5);
 12	
 13	/// The kinds of backends.
 14	pub const Kind = enum { exec };
 15	
 16	/// Configuration for the various backend types.
 17	pub const Config = union(Kind) {
 18	    /// Exec uses posix exec to run a command with a pty.
 19	    exec: termio.Exec.Config,
 20	};
 21	
 22	/// Backend implementations. A backend is responsible for owning the pty
 23	/// behavior and providing read/write capabilities.
 24	pub const Backend = union(Kind) {
 25	    exec: termio.Exec,
 26	
 27	    pub fn deinit(self: *Backend) void {
 28	        switch (self.*) {
 29	            .exec => |*exec| exec.deinit(),
 30	        }
 31	    }
 32	
 33	    pub fn initTerminal(self: *Backend, t: *terminal.Terminal) void {
 34	        switch (self.*) {
 35	            .exec => |*exec| exec.initTerminal(t),
 36	        }
 37	    }
 38	
 39	    pub fn threadEnter(
 40	        self: *Backend,
 41	        alloc: Allocator,
